    def upload_alarms(self, **kwargs):
        """Upload alarms"""

        integrated_ids = kwargs.pop('dist_name', self.default_distname)
        timeout = kwargs.get('timeout', 10)
        return self.nom_factory.nom.upload_alarms(integrated_ids=[integrated_ids], timeout=timeout)

    def convert_alarm_format(self, alarms_netact_format, interface):
        """Convert alarm format"""
        alarms_general_format = []
        for alarm_details in alarms_netact_format:
            logger.debug("#### alarm_details is {}".format(alarm_details))
            alarm_dictionary = {}
            alarm_dictionary['#'] = alarms_netact_format.index(alarm_details) + 1
            try:
                alarm_dictionary['OBJECT'] = alarm_details['dn']
                alarm_dictionary['SEVERITY'] = alarm_details['severity']
                alarm_dictionary['TEXT'] = alarm_details['alarm_text']
                alarm_dictionary['ALARM ID'] = alarm_details['specific_problem']
                alarm_dictionary['FAULT NAME'] = alarm_details['additional_alarm_text1']
                # alarm_dictionary['ACTIVITY'] = alarm_details[] #TBD if needed
                alarm_dictionary['TIME'] = AlarmsVerification().convert_date_format(
                    alarm_details['last_update_notification_time'], interface)
                alarm_dictionary['FAULT ID'] = alarm_details['system_alarm_id']
                alarm_dictionary['srcIPAddr'] = self._parse_additionalText3_param_from_fetched_alarm(
                    'srcIPAddr', alarm_details)
                alarm_dictionary['dstIPAddr'] = self._parse_additionalText3_param_from_fetched_alarm(
                    'dstIPAddr', alarm_details)
            except KeyError as keyError:
                raise AlarmParameterNotFoundException("alarm parameter {} not found".format(
                    keyError))
            except AlarmParameterNotFoundException as e:
                raise AlarmParameterNotFoundException("alarm parameter {} not found".format(e))
            # alarm_dictionary['HEXID'] = alarm_details #TBD if needed
            alarms_general_format.append(alarm_dictionary)
        logger.debug("Converted format:{}".format(alarms_general_format))
        return alarms_general_format

    def _parse_additionalText3_param_from_fetched_alarm(self, parameter_name, alarm_details):
        fetched_fault_id = None
        if alarm_details['additional_alarm_text3'] is not None:
            additional_text3_list = alarm_details['additional_alarm_text3'].split(" ")
            for additionalText3 in additional_text3_list:
                # if parameter_name == 'additionalFaultID' and parameter_name in additionalText3:
                #     fetched_fault_id = additionalText3.split(parameter_name)[1].replace('=', '') if len(
                #         additionalText3.split(parameter_name)) > 1 else None
                #     if fetched_fault_id != 'None':
                #         return fetched_fault_id
                if parameter_name == 'srcIPAddr' and parameter_name in additionalText3:
                    return additionalText3.split(parameter_name)[1].split("=")[1]
                if parameter_name == 'dstIPAddr' and parameter_name in additionalText3:
                    return additionalText3.split(parameter_name)[1].split("=")[1]
            else:
                if parameter_name == 'additionalFaultID' and fetched_fault_id is not None:
                    raise AlarmParameterNotFoundException("{} is not found".format(parameter_name))
                logger.warn("Could not fetch {}.".format(parameter_name))

    def cancel_alarms(self, **kwargs):
        """
        This keyword cancels alarms.

        Parameters:
        alarm_dn (string) - Distinguished name of the alarm
        system_alarm_id (string) -  System alarm identifier of the alarm

        Returns:
        Dict containing operation_id, status and timestamp keys.

        Return type:
        dict
        """

        alarm_dn = kwargs['dist_name']
        system_alarm_id = kwargs.pop('fault_id', None)

        return self.nom_factory.nom.cancel_alarm(alarm_dn=alarm_dn, system_alarm_id=system_alarm_id)
